package com.rappistream.orderprocessor.infrastructure.kafka;  import com.rappistream.orderprocessor.messaging.OrderEvent; import com.rappistream.orderprocessor.ports.OrderEventPublisherPort;  import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Component;  import java.util.concurrent.TimeUnit;  @Component public class KafkaOrderEventPublisherAdapter implements OrderEventPublisherPort {      private final KafkaTemplate<String, OrderEvent> kafkaTemplate;     private final String topic;      public KafkaOrderEventPublisherAdapter(KafkaTemplate<String, OrderEvent> kafkaTemplate,                                            @org.springframework.beans.factory.annotation.Value("${app.kafka.topic:order_events}") String topic) {         this.kafkaTemplate = kafkaTemplate;         this.topic = topic;     }      @Override     public void publish(OrderEvent event) {         try {             kafkaTemplate.send(topic, event.orderId(), event).get(10, TimeUnit.SECONDS);         } catch (Exception e) {             throw new RuntimeException("Failed to publish order event", e);         }     } }
